<?php

namespace App\Service;

final class CrismaQuestSaintCatalog
{
    private const CARLO_USER_PORTRAIT = 'data:image/webp;base64,';

    public static function all(): array
    {
        static $cards;
        if ($cards === null) {
            $cards = json_decode(file_get_contents(__DIR__ . '/../../config/crismaquest/saints.json'), true, 512, JSON_THROW_ON_ERROR);

            // Curadoria final aprovada: usar exatamente o retrato vertical enviado
            // pelo administrador para São Carlo Acutis. Não depende de cache,
            // banco ou carregamento de imagem externa.
            foreach ($cards as &$card) {
                if (($card['slug'] ?? '') === 'sao-carlo-acutis') {
                    $card['image_path'] = self::CARLO_USER_PORTRAIT;
                    $card['image_url'] = self::CARLO_USER_PORTRAIT;
                    $card['image_kind'] = 'Fotografia vertical';
                    $card['source_description'] = 'Retrato vertical fornecido pelo administrador do CrismaQuest.';
                    $card['fallback_image_path'] = 'https://www.vaticannews.va/content/dam/vaticannews/multimedia/2024/maggio/24/Carlo-Acutis.jpg/_jcr_content/renditions/cq5dam.thumbnail.cropped.750.422.jpeg';
                }
            }
            unset($card);
        }
        return $cards;
    }

    public static function enrich(array $card): array
    {
        foreach (self::all() as $art) {
            if ($art['slug'] === ($card['slug'] ?? '')) {
                // A curadoria visual do catálogo é a fonte de verdade.
                // Isso impede registros antigos no banco de sobrescreverem
                // a imagem correta no álbum e na home dos alunos.
                return array_replace($card, $art);
            }
        }
        return $card;
    }
}
